function sortable(key, label2, place2, choices) {
  const name = camel(key);
  const def = Array.isArray(DEFAULTS[key]) ? DEFAULTS[key].map(String) : [];
  const known = (v) => choices.some((c) => c.value === v);
  const items = [
    ...def.filter(known).map((item) => ({ item, enabled: true })),
    ...choices.filter((c) => !def.includes(c.value)).map((c) => ({ item: c.value, enabled: false }))
  ];
  return {
    fields: [
      {
        ...place2,
        name,
        type: "list",
        label: label2,
        itemLabel: "item",
        max: choices.length,
        fields: [
          {
            name: "item",
            type: "select",
            label: { en: "Element", it: "Elemento" },
            options: choices.map((c) => ({ value: c.value, label: c.label }))
          },
          {
            name: "enabled",
            type: "boolean",
            label: { en: "Shown", it: "Visibile" },
            default: true
          }
        ],
        default: items
      }
    ],
    write(values) {
      const list = values[name];
      if (!Array.isArray(list)) return {};
      const out = [];
      for (const it of list) {
        const v = str(rec(it).item);
        if (known(v) && rec(it).enabled !== false && !out.includes(v)) out.push(v);
      }
      return { [key]: out };
    }
  };
}
function flags(key, place2, choices, on = 1, off = 0) {
  const base2 = rec(DEFAULTS[key]);
  const nameOf = (v) => camel(`${key}-${v}`);
  return {
    fields: choices.map(
      (c) => ({
        ...place2,
        name: nameOf(c.value),
        type: "boolean",
        label: c.label,
        default: Boolean(Number(base2[c.value] ?? 0)) || base2[c.value] === true
      })
    ),
    write(values) {
      if (!choices.some((c) => values[nameOf(c.value)] !== void 0)) return {};
      const out = { ...base2 };
      for (const c of choices) {
        const v = values[nameOf(c.value)];
        if (v === void 0) continue;
        if (v) out[c.value] = on;
        else if (off === void 0) delete out[c.value];
        else out[c.value] = off;
      }
      return { [key]: out };
    }
  };
}
