function implicit(key, field, place2, fallback, toOption = (v) => v) {
  const name = camel(key);
  return {
    fields: [{ ...place2, ...field, name, default: fallback }],
    write(values) {
      const v = values[name];
      if (v === void 0 || v === null || v === "" || v === fallback) return {};
      return { [key]: toOption(v) };
    }
  };
}
